+    public async Task<ShipmentDto?> GetShipmentByIdAsync(int id)
+    {
+        var entity = await db.Shipments.FindAsync(id);
+        return entity is null ? null : MapToDto(entity);
+    }
+
+    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto shipment)
+    {
+        var entity = new Data.Shipment
+        {
+            TrackingNumber = "SHP-" + Guid.NewGuid().ToString("N")[..8].ToUpper(),
+            Origin = shipment.Origin,
+            Destination = shipment.Destination,
+            Status = ShipmentStatus.Pending,
+            CreatedDate = DateTime.UtcNow,
+            EstimatedDelivery = shipment.EstimatedDelivery,
+            RecipientName = shipment.RecipientName,
+            Description = shipment.Description,
+            WeightKg = shipment.WeightKg
+        };
+
+        db.Shipments.Add(entity);
+        await db.SaveChangesAsync();
+        return MapToDto(entity);
+    }
+
+    public async Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
+    {
+        var entity = await db.Shipments.FindAsync(id);
+        if (entity is null) return;
+
+        entity.Status = status;
+        if (status == ShipmentStatus.Delivered)
+            entity.ActualDelivery = DateTime.UtcNow;
+
+        await db.SaveChangesAsync();
+    }
+
+    private static ShipmentDto MapToDto(Data.Shipment s) => new()
+    {
+        Id = s.Id,
+        TrackingNumber = s.TrackingNumber,
+        Origin = s.Origin,
+        Destination = s.Destination,
+        Status = s.Status,
+        CreatedDate = s.CreatedDate,
+        EstimatedDelivery = s.EstimatedDelivery,
+        ActualDelivery = s.ActualDelivery,
+        RecipientName = s.RecipientName,
+        Description = s.Description,
+        WeightKg = s.WeightKg
+    };
+}
+

