@page "/"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService
@inject NavigationManager Navigation

<PageTitle>Home — ShipmentTracker</PageTitle>

<h1>Welcome to ShipmentTracker</h1>
<p class="lead">Your logistics management dashboard</p>

@if (shipments is null)
{
    <p><em>Loading dashboard...</em></p>
}
else
{
    <div class="row mb-4">
        <div class="col-md-4">
            <div class="card text-white bg-primary mb-3">
                <div class="card-body">
                    <h5 class="card-title">Total Shipments</h5>
                    <p class="card-text display-6">@shipments.Count</p>
                </div>
            </div>
        </div>
        <div class="col-md-4">
            <div class="card text-white bg-warning mb-3">
                <div class="card-body">
                    <h5 class="card-title">In Transit</h5>
                    <p class="card-text display-6">@shipments.Count(s => s.Status == ShipmentStatus.InTransit)</p>
                </div>
            </div>
        </div>
        <div class="col-md-4">
            <div class="card text-white bg-success mb-3">
                <div class="card-body">
                    <h5 class="card-title">Delivered</h5>
                    <p class="card-text display-6">@shipments.Count(s => s.Status == ShipmentStatus.Delivered)</p>
                </div>
            </div>
        </div>
    </div>

    <div class="card mb-4">
        <div class="card-body">
            <h5 class="card-title">Quick Track</h5>
            <div class="input-group">
                <input type="text" class="form-control" placeholder="Enter tracking number..." @bind="trackingInput" @bind:event="oninput" @onkeydown="HandleTrackKeyDown" />
                <button class="btn btn-primary" @onclick="GoToTrack">Track</button>
            </div>
        </div>
    </div>
}

@code {
    private List<ShipmentDto>? shipments;
    private string trackingInput = string.Empty;

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetShipmentsAsync();
    }

    private void GoToTrack()
    {
        if (!string.IsNullOrWhiteSpace(trackingInput))
            Navigation.NavigateTo($"/track/{Uri.EscapeDataString(trackingInput.Trim())}");
    }

    private void HandleTrackKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            GoToTrack();
    }
}

