                <button class="btn btn-primary" @onclick="GoToTrack">Track</button>
            </div>
        </div>
    </div>
}

@code {
    private List<ShipmentDto>? shipments;
    private string trackingInput = string.Empty;

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetShipmentsAsync();
    }

    private void GoToTrack()
    {
        if (!string.IsNullOrWhiteSpace(trackingInput))
            Navigation.NavigateTo($"/track/{Uri.EscapeDataString(trackingInput.Trim())}");
    }

    private void HandleTrackKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            GoToTrack();
    }
}

