+                        <dd>@(string.IsNullOrEmpty(shipment.Description) ? "—" : shipment.Description)</dd>
+                        <dt>Weight</dt>
+                        <dd>@(shipment.WeightKg.HasValue ? $"{shipment.WeightKg} kg" : "—")</dd>
+                        <dt>Estimated Delivery</dt>
+                        <dd>@(shipment.EstimatedDelivery?.ToString("yyyy-MM-dd") ?? "—")</dd>
+                        @if (shipment.ActualDelivery.HasValue)
+                        {
+                            <dt>Actual Delivery</dt>
+                            <dd>@shipment.ActualDelivery.Value.ToString("yyyy-MM-dd")</dd>
+                        }
+                    </dl>
+                </div>
+            </div>
+        </div>
+    </div>
+}
+
+@code {
+    [Parameter] public string? TrackingNumber { get; set; }
+
+    private string searchInput = string.Empty;
+    private ShipmentDto? shipment;
+    private bool loading;
+    private bool searched;
+
+    protected override async Task OnParametersSetAsync()
+    {
+        if (!string.IsNullOrEmpty(TrackingNumber))
+        {
+            searchInput = TrackingNumber;
+            await Search();
+        }
+    }
+
+    private async Task Search()
+    {
+        var term = searchInput.Trim();
+        if (string.IsNullOrEmpty(term)) return;
+
+        loading = true;
+        searched = true;
+        shipment = null;
+        StateHasChanged();
+
+        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(term);
+        loading = false;
+    }
+
+    private async Task HandleKeyDown(KeyboardEventArgs e)
+    {
+        if (e.Key == "Enter")
+            await Search();
+    }
+
+    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
+    {
+        ShipmentStatus.Pending => "bg-secondary",
+        ShipmentStatus.PickedUp => "bg-info",
+        ShipmentStatus.InTransit => "bg-warning text-dark",
+        ShipmentStatus.OutForDelivery => "bg-primary",
+        ShipmentStatus.Delivered => "bg-success",
+        ShipmentStatus.Cancelled => "bg-danger",
+        _ => "bg-secondary"
+    };
+}
