 @code {
     private List<ShipmentDto>? shipments;
     private string statusFilter = string.Empty;
     private string searchTerm = string.Empty;
     private bool showCreateForm;
     private ShipmentDto newShipment = new();

     protected override async Task OnInitializedAsync()
     {
         await LoadShipments();
     }

     private async Task LoadShipments()
     {
         shipments = await ShipmentService.GetShipmentsAsync(
             string.IsNullOrEmpty(statusFilter) ? null : statusFilter,
             string.IsNullOrEmpty(searchTerm) ? null : searchTerm);
     }

     private void ToggleCreateForm()
     {
         showCreateForm = !showCreateForm;
         if (showCreateForm) newShipment = new();
     }

     private async Task CreateShipment()
     {
         await ShipmentService.CreateShipmentAsync(newShipment);
         showCreateForm = false;
         newShipment = new();
         await LoadShipments();
     }

     private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
     {
         if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
         {
             await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
             await LoadShipments();
         }
     }

     private async Task HandleSearchKeyDown(KeyboardEventArgs e)
     {
         if (e.Key == "Enter")
             await LoadShipments();
     }

     private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
     {
         ShipmentStatus.Pending => "bg-secondary",
         ShipmentStatus.PickedUp => "bg-info",
         ShipmentStatus.InTransit => "bg-warning text-dark",
         ShipmentStatus.OutForDelivery => "bg-primary",
         ShipmentStatus.Delivered => "bg-success",
         ShipmentStatus.Cancelled => "bg-danger",
         _ => "bg-secondary"
     };
 }

