 @attribute [Authorize]
 @inject IShipmentService ShipmentService

 <PageTitle>Shipments — ShipmentTracker</PageTitle>

 <h1>Shipments</h1>

 <div class="row mb-3">
     <div class="col-md-3">
         <select class="form-select" @bind="statusFilter" @bind:after="LoadShipments">
             <option value="">All Statuses</option>
             @foreach (var s in Enum.GetValues<ShipmentStatus>())
             {
                 <option value="@s">@s</option>
             }
         </select>
     </div>
     <div class="col-md-4">
         <div class="input-group">
             <input type="text" class="form-control" placeholder="Search..." @bind="searchTerm" @bind:event="oninput" @onkeydown="HandleSearchKeyDown" />
             <button class="btn btn-outline-secondary" @onclick="LoadShipments">Search</button>
         </div>
     </div>
     <div class="col-md-3">
         <button class="btn btn-primary" @onclick="ToggleCreateForm">
             @(showCreateForm ? "Cancel" : "New Shipment")
         </button>
     </div>
 </div>

 @if (showCreateForm)
 {
     <div class="card mb-4">
         <div class="card-header">Create New Shipment</div>
         <div class="card-body">
             <div class="row g-3">
                 <div class="col-md-4">
                     <label class="form-label">Origin</label>
                     <input type="text" class="form-control" @bind="newShipment.Origin" />
                 </div>
                 <div class="col-md-4">
                     <label class="form-label">Destination</label>
                     <input type="text" class="form-control" @bind="newShipment.Destination" />
                 </div>
                 <div class="col-md-4">
                     <label class="form-label">Recipient Name</label>
                     <input type="text" class="form-control" @bind="newShipment.RecipientName" />
                 </div>
                 <div class="col-md-4">
                     <label class="form-label">Description</label>
                     <input type="text" class="form-control" @bind="newShipment.Description" />
                 </div>
                 <div class="col-md-4">
                     <label class="form-label">Weight (kg)</label>
                     <input type="number" step="0.1" class="form-control" @bind="newShipment.WeightKg" />
                 </div>
                 <div class="col-md-4">
                     <label class="form-label">Estimated Delivery</label>
                     <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
                 </div>
                 <div class="col-12">
                     <button class="btn btn-success" @onclick="CreateShipment">Create</button>
                 </div>
             </div>
         </div>
     </div>
 }

 @if (shipments is null)
 {
     <p><em>Loading...</em></p>
 }
 else if (shipments.Count == 0)
 {
     <p>No shipments found.</p>
 }
 else
 {
     <table class="table table-striped">
         <thead>
             <tr>
                 <th>Tracking #</th>
                 <th>Origin</th>
                 <th>Destination</th>
                 <th>Status</th>
                 <th>Recipient</th>
                 <th>Est. Delivery</th>
                 <th>Update Status</th>
             </tr>
         </thead>
         <tbody>
             @foreach (var s in shipments)
             {
                 <tr>
                     <td><a href="/track/@s.TrackingNumber">@s.TrackingNumber</a></td>
                     <td>@s.Origin</td>
                     <td>@s.Destination</td>
                     <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                     <td>@s.RecipientName</td>
                     <td>@(s.EstimatedDelivery?.ToString("yyyy-MM-dd") ?? "—")</td>
                     <td>
                         <select class="form-select form-select-sm" value="@s.Status"
                             @onchange="async e => await UpdateStatus(s, e)">
                             @foreach (var st in Enum.GetValues<ShipmentStatus>())
                             {
                                 <option value="@st">@st</option>
                             }
                         </select>
                     </td>
                 </tr>
             }
         </tbody>
     </table>
 }

 @code {
     private List<ShipmentDto>? shipments;
     private string statusFilter = string.Empty;
     private string searchTerm = string.Empty;
     private bool showCreateForm;
     private ShipmentDto newShipment = new();

     protected override async Task OnInitializedAsync()
     {
         await LoadShipments();
     }

     private async Task LoadShipments()
     {
         shipments = await ShipmentService.GetShipmentsAsync(
             string.IsNullOrEmpty(statusFilter) ? null : statusFilter,
             string.IsNullOrEmpty(searchTerm) ? null : searchTerm);
     }

     private void ToggleCreateForm()
     {
         showCreateForm = !showCreateForm;
         if (showCreateForm) newShipment = new();
     }

     private async Task CreateShipment()
     {
         await ShipmentService.CreateShipmentAsync(newShipment);
         showCreateForm = false;
         newShipment = new();
         await LoadShipments();
     }

     private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
     {
         if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
         {
             await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
             await LoadShipments();
         }
     }

     private async Task HandleSearchKeyDown(KeyboardEventArgs e)
     {
         if (e.Key == "Enter")
             await LoadShipments();
     }

     private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
     {
         ShipmentStatus.Pending => "bg-secondary",
         ShipmentStatus.PickedUp => "bg-info",
         ShipmentStatus.InTransit => "bg-warning text-dark",
         ShipmentStatus.OutForDelivery => "bg-primary",
         ShipmentStatus.Delivered => "bg-success",
         ShipmentStatus.Cancelled => "bg-danger",
         _ => "bg-secondary"
     };
 }

