             @if (shipment.Status != ShipmentStatus.Cancelled)
             {
                 <div class="d-flex justify-content-between mb-4 position-relative">
                     @for (int i = 0; i < steps.Length; i++)
                     {
                         var step = steps[i];
                         var isActive = (int)shipment.Status >= (int)step;
                         <div class="text-center flex-fill">
                             <div class="rounded-circle d-inline-flex align-items-center justify-content-center @(isActive ? "bg-success" : "bg-secondary")"
                                  style="width: 36px; height: 36px; color: white; font-weight: bold;">
                                 @(i + 1)
                             </div>
                             <div class="small mt-1">@step</div>
                         </div>
                     }
                 </div>
                 <div class="progress mb-4" style="height: 8px;">
                     @{
                         var currentIdx = Array.IndexOf(steps, shipment.Status);
                         var pct = steps.Length > 1 ? (int)(currentIdx * 100.0 / (steps.Length - 1)) : 0;
                     }
                     <div class="progress-bar bg-success" role="progressbar" style="width: @pct%"></div>
                 </div>
             }
             else
             {
                 <div class="alert alert-danger mb-4">This shipment has been cancelled.</div>
             }

             <div class="row">
                 <div class="col-md-6">
                     <dl>
                         <dt>Status</dt>
                         <dd><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></dd>
                         <dt>Origin</dt>
                         <dd>@shipment.Origin</dd>
                         <dt>Destination</dt>
                         <dd>@shipment.Destination</dd>
                     </dl>
                 </div>
                 <div class="col-md-6">
                     <dl>
                         <dt>Recipient</dt>
                         <dd>@shipment.RecipientName</dd>
                         <dt>Description</dt>
                         <dd>@(string.IsNullOrEmpty(shipment.Description) ? "—" : shipment.Description)</dd>
                         <dt>Weight</dt>
                         <dd>@(shipment.WeightKg.HasValue ? $"{shipment.WeightKg} kg" : "—")</dd>
                         <dt>Estimated Delivery</dt>
                         <dd>@(shipment.EstimatedDelivery?.ToString("yyyy-MM-dd") ?? "—")</dd>
                         @if (shipment.ActualDelivery.HasValue)
                         {
                             <dt>Actual Delivery</dt>
                             <dd>@shipment.ActualDelivery.Value.ToString("yyyy-MM-dd")</dd>
                         }
                     </dl>
                 </div>
             </div>
         </div>
     </div>
 }

 @code {
     [Parameter] public string? TrackingNumber { get; set; }

     private string searchInput = string.Empty;
     private ShipmentDto? shipment;
     private bool loading;
     private bool searched;

     protected override async Task OnParametersSetAsync()
     {
         if (!string.IsNullOrEmpty(TrackingNumber))
         {
             searchInput = TrackingNumber;
             await Search();
         }
     }

     private async Task Search()
     {
         var term = searchInput.Trim();
         if (string.IsNullOrEmpty(term)) return;

         loading = true;
         searched = true;
         shipment = null;
         StateHasChanged();

         shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(term);
         loading = false;
     }

     private async Task HandleKeyDown(KeyboardEventArgs e)
     {
         if (e.Key == "Enter")
             await Search();
     }

     private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
     {
         ShipmentStatus.Pending => "bg-secondary",
         ShipmentStatus.PickedUp => "bg-info",
         ShipmentStatus.InTransit => "bg-warning text-dark",
         ShipmentStatus.OutForDelivery => "bg-primary",
         ShipmentStatus.Delivered => "bg-success",
         ShipmentStatus.Cancelled => "bg-danger",
         _ => "bg-secondary"
     };
 }

